  'ab.subtitle': 'Browser-based optical design and simulation. Engine {engine} · project schema v1.',
  'ab.numbers': 'What the numbers are',
  'ab.rays': 'Layouts, spot diagrams, ray and OPD fans, field curvature, distortion and longitudinal aberration come from exact real-ray tracing (vector refraction and reflection, exact intersections with conic, aspheric, biconic and Zernike surfaces).',
  'ab.paraxial': 'System data (EFL, BFL, pupils, F/#) and Seidel sums are paraxial or third-order and are labelled as such.',
  'ab.diffraction': 'PSF, Strehl ratio and MTF use scalar diffraction of the real-ray wavefront. The FFT PSF neglects pupil aberrations; the Huygens PSF includes them. Only the Vector PSF uses vector (Debye–Wolf, high-NA) diffraction.',
  'ab.physics': 'Fresnel losses, thin-film coatings, polarisation ray tracing (isotropic media and uniaxial crystals), two-surface ghosts and non-sequential tracing with light sources, detectors, scattering and CAD solids are geometric optics with the stated models.',
  'ab.wave': 'Wave optics: exact step-index fibre modes, scalar physical-optics propagation (POP) and beam propagation (BPM) through the glass, and 2D and rotationally symmetric 3D FDTD Maxwell solvers.',
  'ab.materials': 'Material data are transcribed from public datasheets, literature and manufacturer catalogues; use outside a material\'s wavelength range is flagged.',
  'ab.limits': 'Not modelled',
  'ab.limitsText': 'Biaxial and optically active media, stress birefringence, thermal gradients, measured (tabulated) BSDF scattering and multi-order efficiency of diffractive surfaces in the ray trace (gratings can be analysed separately with RCWA). See docs/OPTICAL_ENGINE.md, "Known limitations".',
  'ab.validation': 'Validation',
  'ab.validationText': 'Every physics module is checked against analytic or independent benchmarks in an automated suite: Snell and Fresnel, total internal reflection, mirror and lensmaker focus, plate displacement, Seidel sums against real rays, thin films, Gaussian beams, fibre modes, FDTD and more. See docs/VALIDATION.md.',
