  'op.rms_spot': 'RMS spot radius',
  'op.rms_spot.desc': 'Real-ray RMS spot radius integrated over the pupil with Gaussian quadrature (rings x arms), weighted by field and wavelength weights. Target 0 minimises; a target above 0 asks for a spot of that RMS radius (mm, e.g. 0.02 for 20 µm).',
  'op.throughput': 'Energy throughput',
  'op.throughput.desc': 'Fraction of entrance-pupil power reaching the image: vignetting, Fresnel / coating surface losses and bulk absorption (target 1 maximises).',
  'op.rms_wavefront': 'RMS wavefront error',
  'op.rms_wavefront.desc': 'Pupil-area RMS of the real-ray OPD in waves (Gaussian quadrature). One wavelength, or all of them weighted against the reference sphere of the primary chief ray, so lateral and axial colour count (in waves of the primary wavelength). Piston is removed, and with the centroid reference also tilt. Target 0 minimises.',
  'op.mtf': 'Diffraction MTF at frequency',
  'op.mtf.desc': 'FFT-based diffraction MTF (polychromatic) at the given spatial frequency for one field, or the field-weighted mean of all fields; tangential, sagittal or their average. Target 1 with a weight maximises contrast.',
