  'op.detector_size': 'Beam diameter on detector (D4σ)',
  'op.detector_size.desc': 'Second-moment beam diameter D4σ = 4σ in the plane of a detector (the 1/e² diameter of a Gaussian beam, the diameter of a uniform disc), from the project light sources by the direct-path trace (seeded, through the lens surfaces; no ghosts). x, y or their average. Targets accept units, e.g. 150 um.',
  'op.detector_power': 'Power on detector',
  'op.detector_power.desc': 'Fraction of the emitted source power the detector accepts (direct path: Fresnel or coating losses, absorption, apertures, acceptance angle). Target 1 maximises; it changes in steps of about 1/rays, so combine it with the beam diameter or use the global algorithm.',
  'op.surface_reflectance': 'Surface reflectance',
  'op.surface_reflectance.desc': 'Unpolarised reflectance of the surface (coating or bare Fresnel; mirrors: their coating) averaged over the rays that reach it (pupil quadrature, all or one field / wavelength). Target 0 suppresses ghosts; use coating variables to optimise the coating in the system.',
  'opt.noVarsEmpty': 'No variables: nothing may change yet. Tick V next to radii and thicknesses in the Lens Data Editor, or add variables in the Merit Function tab.',
  'opt.atBound': 'at bound',
  'op.max_lateral_color': 'Maximum lateral colour',
  'op.max_lateral_color.desc': '|Lateral colour| at most the target (µm, one-sided): the chief ray of the shortest minus the longest wavelength on the image, at the chosen field or the largest one.',
  'op.min_relative_illumination': 'Minimum relative illumination',
  'op.min_relative_illumination.desc': 'Relative illumination at least the target (a fraction of the axis, one-sided) at the chosen field or the largest one: the corner brightness a sensor sees.',
  'op.max_cra': 'Maximum chief-ray angle',
  'op.max_cra.desc': 'The chief-ray angle on the image surface at most the target (degrees, one-sided) at the chosen field or the largest one. Image sensors accept light only up to their own chief-ray angle.',
  'mf.largestField': 'largest',
  'ow.maxLateral': 'Lateral colour at most',
  'ow.maxLateralHint': '|Lateral colour| at the largest field (shortest minus longest wavelength). On by default for the sharpest-image goals, at the current value, so colour fringes cannot grow.',
