  'mf.fixed': 'fixed',
  'mf.fixedHint': 'No variable can change this operand (the edge of a plane-parallel plate, or a thickness that is not a variable): it only adds a constant to the merit function. Remove it, or make the thickness a variable.',
  'mf.primaryWl': 'primary',
  'mf.reference': 'Reference',
  'mf.referenceHint': 'Spot about its centroid or the chief ray; wavefront with or without tilt',
  'mf.extra': 'Options',
  'mf.extraHint': 'MTF: frequency (cycles/mm) and direction · spot and wavefront: reference · beam diameter: axis',
  'mf.note': 'Merit function MF = √(Σ wₖ (vₖ − tₖ)² / Σ wₖ). The RMS spot and wavefront operands contribute one residual per ray, so least-squares solvers see the whole aberration; with a target above 0 they contribute the single error (RMS − target). With exact limits (the default) the limits are not in this sum: each is met to its tolerance and the weights only balance the goals. With weighted limits every operand is in the sum and one-sided bounds contribute only when violated; errors are in each operand\'s own unit (mm, %, waves), so a violated limit in mm outweighs a spot of a few µm and the weights decide the balance.',
  'ow.spot_size': 'A spot of a given size (RMS radius)',
  'ow.beam_size': 'A beam of a given diameter on a detector (D4σ)',
  'ow.rms_spotHint': 'Minimise the RMS spot radius over the fields and wavelengths (geometric, real rays).',
  'ow.rms_wavefrontHint': 'Minimise the RMS wavefront error over the fields and all wavelengths (colour included): for nearly diffraction-limited systems.',
  'ow.spot_sizeHint': 'Reach a spot of this RMS radius (geometric, real rays), e.g. a defocused beam on a sensor; with the image distance as a variable it finds the plane where the spot has that size.',
  'ow.beam_sizeHint': 'The beam from the project\'s light sources on a detector, by the direct-path trace: a Gaussian beam source gives its real 1/e² diameter including diffraction (M² λ / π w₀). The power on the detector is kept up as well (weight 0.1).',
