  'dg.PARAXIAL_AIMING.cause': 'With paraxial ray aiming the rays go through the paraxial entrance pupil, and the pupil is aberrated: they miss the stop points they stand for. Spots, MTF, illumination, vignetting and chief-ray results then refer to a pupil the lens does not have.',
  'dg.PARAXIAL_AIMING.fix': 'Switch ray aiming to real in the system settings: the rays then fill the stop.',
  'dg.CB_MATERIAL_IGNORED.cause': 'A coordinate break has a material, but breaks do not change the medium.',
  'dg.CB_MATERIAL_IGNORED.fix': 'Clear the material of the coordinate break.',
  'dg.COATING_IGNORED.cause': 'The coating sits where it has no effect (on a break, the object or image, an ideal lens, or a mirror without a substrate).',
  'dg.COATING_IGNORED.fix': 'Move the coating to a refracting surface or a mirror, or give the coating a substrate index.',
  'dg.COATING_MATERIAL.cause': 'A coating layer refers to a material the project does not know.',
  'dg.COATING_MATERIAL.fix': 'Edit the coating and pick a known layer material or a fixed index.',
