  'dg.COATING_NAME.fix': 'Rename the project coating in the coating editor.',
  'dg.COATING_RANGE.cause': 'A coating layer material is used outside its data range at some wavelengths.',
  'dg.COATING_RANGE.fix': 'Check the wavelengths, or use a layer material with data at those wavelengths.',
  'dg.COATING_SUBSTRATE_IGNORED.cause': "The coating's substrate index only applies on mirrors; on a lens the glass is the substrate.",
  'dg.COATING_SUBSTRATE_IGNORED.fix': 'Nothing to do, unless the coating was meant for a mirror.',
  'dg.CONFIG_INVALID.cause': 'A configuration sets a value that cannot be applied (or that a solve also controls).',
  'dg.CONFIG_INVALID.fix': 'Open Configurations and correct or remove the row.',
  'dg.DOE_ACTIVE.cause': 'A diffractive surface is traced with the exact grating equation; Seidel sums, CAD export and non-sequential tracing ignore its phase.',
  'dg.DOE_ACTIVE.fix': 'Use real-ray analyses for this surface.',
  'dg.DOE_IGNORED.cause': 'A diffractive phase is set where it cannot act (object, image or coordinate break).',
  'dg.DOE_IGNORED.fix': 'Remove the phase terms, or move them to a refracting surface.',
  'dg.FIELD_AFOCAL.cause': 'The system is afocal, so image-height fields have no meaning.',
  'dg.FIELD_AFOCAL.fix': 'Use angle or object-height fields.',
  'dg.FIELD_SCALE.cause': 'A paraxial image height cannot be converted to an object field for this system.',
  'dg.FIELD_SCALE.fix': 'Use angle, object-height or real image-height fields.',
  'dg.FIELD_UNREACHABLE.cause': 'No real chief ray reaches the requested image height.',
  'dg.FIELD_UNREACHABLE.fix': 'Reduce the image height, or use angle fields.',
  'dg.GRATING_PARAXIAL.cause': "A linear grating's deviation is not part of the paraxial data.",
  'dg.GRATING_PARAXIAL.fix': 'Use real-ray analyses for the grating.',
  'dg.IDEAL_DOE_IGNORED.cause': 'An ideal lens ignores diffractive phase terms.',
  'dg.IDEAL_DOE_IGNORED.fix': 'Remove the phase terms or change the surface type.',
  'dg.IDEAL_LENS.cause': 'An ideal lens images without aberrations; its optical path is exact for one object distance.',
  'dg.IDEAL_LENS.fix': 'Set the OPD conjugate in the Inspector if the object is at another distance.',
  'dg.IDEAL_MEDIA.cause': 'An ideal lens needs the same medium on both sides.',
  'dg.IDEAL_MEDIA.fix': 'Set the ideal lens material to the medium in front of it.',
  'dg.IDEAL_SHAPE_IGNORED.cause': 'An ideal lens is a plane: radius, conic and aspheric terms are ignored.',
  'dg.IDEAL_SHAPE_IGNORED.fix': 'Clear them, or change the surface type.',
  'dg.MIRROR_COATING.cause': "The mirror's reflectance comes from its coating (thin-film calculation) in throughput and polarisation analyses.",
  'dg.MIRROR_COATING.fix': 'Nothing to do; edit the coating to change the reflectance.',
  'dg.NEGATIVE_EDGE_THICKNESS.cause': 'The element is thinner than zero at its edge: the surfaces cross, so it cannot be made.',
  'dg.NEGATIVE_EDGE_THICKNESS.fix': 'Increase the centre thickness, reduce the semi-diameter, or flatten the surfaces.',
  'dg.NONPOSITIVE_GLASS_THICKNESS.cause': 'A glass element has zero or negative centre thickness.',
  'dg.NONPOSITIVE_GLASS_THICKNESS.fix': 'Give the glass a positive thickness.',
  'dg.NON_AXIAL.cause': 'With coordinate breaks the paraxial values are computed on the unfolded axis and are approximate.',
  'dg.NON_AXIAL.fix': 'Rely on real-ray analyses for tilted systems.',
  'dg.PARAXIAL_FAILED.cause': 'The paraxial trace failed, so EFL, pupils and F/# are not available.',
  'dg.PARAXIAL_FAILED.fix': 'Check the prescription for afocal or degenerate settings; undo the last change if needed.',
  'dg.RAY_FAILED.miss.cause': 'A ray misses a surface: the beam is wider than the surface, or a surface bends it too strongly.',
  'dg.RAY_FAILED.miss.fix': 'Reduce the field or the aperture, or make that surface flatter or larger.',
  'dg.RAY_FAILED.tir.cause': 'A ray is totally internally reflected: it reaches a glass–air surface too steeply.',
  'dg.RAY_FAILED.tir.fix': 'Reduce the field angle or the aperture, or the curvature at that surface.',
  'dg.RAY_FAILED.clip.cause': 'A ray is clipped by a fixed semi-diameter (vignetting).',
  'dg.RAY_FAILED.clip.fix': 'Enlarge that semi-diameter or set it to automatic, or reduce the field or aperture.',
  'dg.OBSCURATION.cause': 'This surface has a central obscuration: rays inside it are blocked.',
  'dg.OBSCURATION.fix': 'No action needed; diffraction analyses (PSF, MTF) include it.',
  'dg.OBSCURATION_IGNORED.cause': 'A central obscuration on the object or image surface or a coordinate break has no effect.',
  'dg.OBSCURATION_IGNORED.fix': 'Put the obscuration on a refracting, reflecting or dummy surface.',
  'dg.RAY_FAILED.obscured.cause': 'A ray is blocked by a central obscuration.',
  'dg.RAY_FAILED.obscured.fix': 'Expected for rays in the obscured centre of the pupil; reduce the obscuration radius if the ray should pass.',
  'dg.ODD_ASPHERE_PARAXIAL.cause': 'The r and r³ terms of the odd asphere have no paraxial or third-order equivalent.',
  'dg.ODD_ASPHERE_PARAXIAL.fix': 'Judge their effect with real-ray analyses (spot, fans, MTF); paraxial data and Seidel sums omit them.',
