  'dg.ODD_ASPHERE_CONE.fix': 'Set β1 to 0 unless the cone is intended.',
  'dg.RAY_FAILED.domain.cause': 'A ray lands where the surface shape is not defined (beyond a conic or polynomial range).',
  'dg.RAY_FAILED.domain.fix': 'Reduce the aperture, or the curvature or coefficients of that surface.',
  'dg.RAY_FAILED.converge.cause': 'The intersection with a strongly aspheric surface did not converge.',
