  'imp.line': 'Rivi',
  'ab.subtitle': 'Selainpohjainen optinen suunnittelu ja simulointi. Moottori {engine} · projektiskeema v1.',
  'ab.numbers': 'Mitä luvut ovat',
  'ab.rays': 'Asettelut, pistekaaviot, säde- ja OPD-viuhkat, kentän kaarevuus, vääristymä ja pitkittäisaberraatio tulevat tarkasta todellisten säteiden jäljityksestä (vektorimuotoinen taittuminen ja heijastuminen, tarkat leikkauspisteet kartio-, asfääri-, bikartio- ja Zernike-pintojen kanssa).',
  'ab.paraxial': 'Järjestelmätiedot (EFL, BFL, pupillit, F/#) ja Seidelin summat ovat paraksiaalisia tai kolmannen kertaluvun arvoja, ja ne on merkitty sellaisiksi.',
  'ab.diffraction': 'PSF, Strehlin suhde ja MTF perustuvat todellisten säteiden aaltorintaman skalaariseen diffraktioon. FFT-PSF jättää pupillin aberraatiot huomiotta; Huygens-PSF ottaa ne mukaan. Vain vektori-PSF käyttää vektoridiffraktiota (Debye–Wolf, suuri NA).',
  'ab.physics': 'Fresnel-häviöt, ohutkalvopinnoitteet, polarisaatiosäteenjäljitys (isotrooppiset väliaineet ja yksiakseliset kiteet), kahden pinnan haamuheijastukset sekä epäsekventiaalinen jäljitys valonlähteineen, ilmaisimineen, sirontoineen ja CAD-kappaleineen ovat geometrista optiikkaa ilmoitetuilla malleilla.',
  'ab.wave': 'Aalto-optiikka: porrasindeksikuitujen tarkat moodit, skalaarinen fysikaalisen optiikan eteneminen (POP) ja keilan eteneminen lasin läpi (BPM) sekä 2D- ja pyörähdyssymmetriset 3D-FDTD-Maxwell-ratkaisijat.',
  'ab.materials': 'Materiaalitiedot on koottu julkisista tuotetiedoista, kirjallisuudesta ja valmistajien luetteloista; käyttö materiaalin aallonpituusalueen ulkopuolella merkitään.',
  'ab.limits': 'Ei mallinneta',
  'ab.limitsText': 'Kaksiakselisia ja optisesti aktiivisia väliaineita, jännityskahtaistaittavuutta, lämpötilagradientteja, mitattua (taulukoitua) BSDF-sirontaa eikä diffraktiivisten pintojen usean kertaluvun hyötysuhdetta säteenjäljityksessä (hilat voi analysoida erikseen RCWA:lla). Katso docs/OPTICAL_ENGINE.md, ”Known limitations”.',
  'ab.validation': 'Validointi',
  'ab.validationText': 'Jokainen fysiikkamoduuli tarkistetaan analyyttisiä tai riippumattomia vertailukohtia vasten automaattisessa testisarjassa: Snell ja Fresnel, kokonaisheijastus, peilin ja linssintekijän polttoväli, levyn aiheuttama siirtymä, Seidelin summat todellisia säteitä vasten, ohutkalvot, Gaussin keilat, kuitumoodit, FDTD ja muuta. Katso docs/VALIDATION.md.',
  'sp.hexapolar': 'Heksapolaarinen',
