  'opt.status.infeasible': 'rajat eivät täyty',
  'mf.limits': 'Rajat',
  'mf.limits.exact': 'tarkat',
  'mf.limits.penalty': 'painotetut',
  'mf.limitsHint': 'Tarkat: rajat ja ensimmäisen kertaluvun tavoitteet (polttoväli, F/#, pituus, reunapaksuudet, vääristymä…) täytetään toleranssiinsa painosta riippumatta (augmented Lagrangian), ja ansiofunktiossa ovat vain tavoitteet. Jokaiselle rajalle lasketaan hinta: kuinka paljon ansiofunktio paranisi, jos rajaa löysättäisiin. Painotetut: jokainen operandi on painotettu termi yhdessä ansiofunktiossa, kuten perinteisissä optimoijissa.',
  'mf.role': 'Rooli',
  'mf.role.objective': 'Tavoite',
  'mf.role.constraint': 'Raja',
  'mf.role.auto': 'Auto: {r}',
  'mf.roleHint': 'Tavoite: ansiofunktion termi, jota minimoidaan painollaan. Raja: täytetään toleranssiinsa (tarkat rajat). Auto: rajat ja ensimmäisen kertaluvun tavoitteet ovat rajoja, kuvanlaatu on tavoite.',
