  'td.title': 'Kompromissi: {name}',
  'td.hint': 'Jokainen piste on linssi optimoituna uudelleen niin, että tämä raja on tarkalleen siinä arvossa (lähtien tästä tuloksesta). Käyrä näyttää, mitä raja maksaa: katkoviiva on tämän tuloksen hinta (ensimmäinen kertaluku), ja käyrä näyttää, kuinka pitkälle se pätee. Minkä tahansa pisteen voi näyttää tuloksena ja ottaa käyttöön.',
