export const dictionaries = { en, fi }

export function translate(lang: 'en' | 'fi', key: string, vars?: Record<string, string | number>): string {
  let s = dictionaries[lang][key] ?? en[key] ?? key
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replace(`{${k}}`, String(v))
  return s
}

/** True when the English dictionary defines the key (dynamic keys with an engine fallback). */
export function hasKey(key: string): boolean {
  return key in en
}

export function useT() {
  const lang = useUiStore((s) => s.lang)
  return (key: string, vars?: Record<string, string | number>) => translate(lang, key, vars)
}
